parameters.jsCode:
// Code node "Route update" (Run Once for All Items)
// Authoritative access control + routing. The trigger's chat filter is the
// first gate; this is the second. Anything not from your private chat is
// dropped silently (returning [] ends the execution).
//
// Output `route`: 0 = voice, 1 = text, 2 = button tap (callback)

const allowed = String($env.TELEGRAM_CHAT_ID || '').trim();
if (!allowed) throw new Error('TELEGRAM_CHAT_ID is not set in the environment');

const u = $('Telegram Trigger').first().json;
const MAX_VOICE_SECONDS = 300;

// ── Button taps ────────────────────────────────────────────
if (u.callback_query) {
  const cq = u.callback_query;
  const chatId = String(cq.message?.chat?.id ?? '');
  const fromId = String(cq.from?.id ?? '');
  if (chatId !== allowed || fromId !== allowed) return [];

  const m = String(cq.data || '').match(/^(ap|no):(\d{1,18})$/);
  if (!m) return [];

  return [{
    json: {
      route: 2,
      kind: 'callback',
      chatId,
      callbackId: cq.id,
      messageId: cq.message.message_id,
      action: m[1] === 'ap' ? 'approve' : 'decline',
      proposalId: m[2],
    },
  }];
}

// ── Messages ───────────────────────────────────────────────
const msg = u.message;
if (!msg) return [];

const chatId = String(msg.chat?.id ?? '');
if (msg.chat?.type !== 'private' || chatId !== allowed || String(msg.from?.id ?? '') !== allowed) {
  return [];
}

const audio = msg.voice || msg.audio;
if (audio) {
  if ((audio.duration || 0) > MAX_VOICE_SECONDS) {
    return [{ json: { route: 1, kind: 'text', chatId,
      text: `[System note: the user sent a voice message longer than ${MAX_VOICE_SECONDS / 60} minutes, which was not processed. Ask them to send a shorter one.]` } }];
  }
  return [{
    json: {
      route: 0,
      kind: 'voice',
      chatId,
      fileId: audio.file_id,
      mimeType: audio.mime_type || 'audio/ogg',
    },
  }];
}

if (typeof msg.text === 'string' && msg.text.trim()) {
  const text = msg.text.trim() === '/start' ? 'Hello! Briefly introduce yourself.' : msg.text.trim();
  return [{ json: { route: 1, kind: 'text', chatId, text } }];
}

return []; // stickers, photos, etc.: ignored

parameters.jsonBody:
={{ JSON.stringify({ contents: [{ parts: [
  { text: 'Transcribe this voice message verbatim, in its original language. Output only the transcript.' },
  { inlineData: { mimeType: $('Route update').first().json.mimeType, data: $json.audioB64 } }
] }] }) }}

parameters.jsCode:
// Code node "Prepare agent input" (Run Once for All Items)
// Joins the voice path (Gemini transcript) and the text path into one shape.

const r = $('Route update').first().json;
let userText = r.text;

if (r.kind === 'voice') {
  const res = $input.first().json;
  userText = (res.candidates?.[0]?.content?.parts || [])
    .filter(p => !p.thought && typeof p.text === 'string')
    .map(p => p.text)
    .join(' ')
    .trim();
  if (!userText) userText = '[The voice message was empty or inaudible.]';
}

return [{
  json: {
    chatId: r.chatId,
    inputMode: r.kind,                    // 'voice' | 'text'
    userText: String(userText).slice(0, 4000),
    sessionKey: `telegram-${r.chatId}`,   // Postgres chat memory key
  },
}];

// Code node "Parse + validate" (Run Once for All Items)
// The agent can only *describe* suggestions. This deterministic step decides
// which of them are well-formed enough to show you. Nothing here executes them.

const ctx = $('Prepare agent input').first().json;
const tz = $env.GENERIC_TIMEZONE || 'Europe/Paris';
const MAX_PROPOSALS = 3;
const raw = String($input.first().json.output ?? '');

function extractJson(s) {
  const t = s.replace(/```(?:json)?/gi, '').trim();
  const a = t.indexOf('{');
  const b = t.lastIndexOf('}');
  if (a === -1 || b <= a) return null;
  try { return JSON.parse(t.slice(a, b + 1)); } catch { return null; }
}

const clean = (v, max) => String(v ?? '')
  .replace(/[\u0000-\u001f\u007f]/g, ' ')
  .replace(/\s+/g, ' ')
  .trim()
  .slice(0, max);

const HAS_OFFSET = /(?:[zZ]|[+-]\d{2}:?\d{2})$/;
const fmtDay = d => d.toLocaleDateString('en-GB', { weekday: 'short', day: 'numeric', month: 'short', timeZone: tz });
const fmtTime = d => d.toLocaleTimeString('en-GB', { hour: '2-digit', minute: '2-digit', timeZone: tz });

function validate(p) {
  if (!p || typeof p !== 'object') return { error: 'not an object' };
  if (p.type !== 'calendar_event') return { error: `unsupported type ${p.type}` };

  const title = clean(p.title, 120);
  if (!title) return { error: 'missing title' };

  const startStr = String(p.start || '').trim();
  const endStr = String(p.end || '').trim();
  if (!HAS_OFFSET.test(startStr) || !HAS_OFFSET.test(endStr)) return { error: 'dates need a timezone offset' };

  const start = new Date(startStr);
  const end = new Date(endStr);
  if (isNaN(start) || isNaN(end)) return { error: 'invalid date' };
  if (end <= start) return { error: 'end before start' };
  if (end - start > 12 * 3600e3) return { error: 'longer than 12 hours' };

  const now = Date.now();
  if (start.getTime() < now - 3600e3) return { error: 'in the past' };
  if (start.getTime() > now + 366 * 86400e3) return { error: 'more than a year ahead' };

  const location = clean(p.location, 150);
  const description = clean(p.description, 500);
  const reason = clean(p.reason, 200);

  const sameDay = fmtDay(start) === fmtDay(end);
  const when = sameDay
    ? `${fmtDay(start)}, ${fmtTime(start)}–${fmtTime(end)}`
    : `${fmtDay(start)} ${fmtTime(start)} → ${fmtDay(end)} ${fmtTime(end)}`;

  const summary = [
    `📅 ${title}`,
    `🕒 ${when}`,
    location && `📍 ${location}`,
    reason && `💡 ${reason}`,
  ].filter(Boolean).join('\n');

  return {
    value: {
      kind: 'calendar_event',
      // The payload is the ONLY thing used when you tap Approve.
      payload: { title, start: start.toISOString(), end: end.toISOString(), location, description },
      summary,
    },
  };
}

const parsed = extractJson(raw);
let reply = '';
let proposals = [];

if (parsed && typeof parsed === 'object') {
  reply = String(parsed.reply ?? '');
  proposals = Array.isArray(parsed.proposals) ? parsed.proposals : [];
} else {
  reply = raw; // model ignored the JSON format: still answer, but propose nothing
}

const valid = [];
const rejected = [];
for (const p of proposals.slice(0, 10)) {
  const r = validate(p);
  if (r.value && valid.length < MAX_PROPOSALS) valid.push(r.value);
  else if (r.error) rejected.push(r.error);
}

reply = reply
  .replace(/https?:\/\/\S+/gi, '')
  .replace(/[*_#`]/g, '')
  .replace(/\s+/g, ' ')
  .trim()
  .slice(0, 1500);

if (!reply) reply = valid.length ? 'I have a suggestion for you.' : "Sorry, I couldn't put an answer together.";
if (rejected.length) reply += ` (I dropped ${rejected.length} suggestion${rejected.length > 1 ? 's' : ''} that had invalid details.)`;

return [{
  json: {
    chatId: ctx.chatId,
    inputMode: ctx.inputMode,
    replyRoute: ctx.inputMode === 'voice' ? 0 : 1,  // 0 = voice reply, 1 = text reply
    text: reply,                                     // "Speak" sub-workflow input contract
    reply,
    proposals: valid,
    rejectedProposals: rejected,
  },
}];

// Code node "One item per proposal" (Run Once for All Items)
// Returning [] (no proposals) simply ends this branch.

const p = $('Parse + validate').first().json;
return (p.proposals || []).map(x => ({
  json: { chatId: p.chatId, kind: x.kind, payload: x.payload, summary: x.summary },
}));

parameters.query:
INSERT INTO assistant.proposals (chat_id, kind, payload, summary, expires_at)
VALUES ($1, $2, $3::jsonb, $4, now() + make_interval(hours => $5::int))
RETURNING id, chat_id, summary, expires_at;

parameters.jsonBody:
={{ JSON.stringify({
  chat_id: $json.chat_id,
  text: $json.summary + '\n\nApprove to add it. Expires in ' + $('Config').first().json.proposalTtlHours + ' h.',
  reply_markup: { inline_keyboard: [[
    { text: '✅ Approve', callback_data: 'ap:' + $json.id },
    { text: '❌ Decline', callback_data: 'no:' + $json.id }
  ]] }
}) }}

parameters.jsCode:
// Code node "Decision outcome" (Run Once for All Items)
// Input: the row returned by the atomic "Claim decision" query, or an empty
// item if the proposal doesn't exist (node has alwaysOutputData on).
// Output `route`: 0 = create the event, 1 = just update the card.

const r = $('Route update').first().json;
const row = $input.first().json || {};
const base = row.summary || 'This suggestion';

let route = 1;
let toast;
let editText;

if (!row.id) {
  toast = 'Suggestion not found';
  editText = `${base}\n\n⚠️ This suggestion no longer exists.`;
} else if (row.ok && row.status === 'approved') {
  route = 0;
  toast = 'Adding…';
  editText = null; // set by "Mark executed" / "Mark failed"
} else if (row.ok && row.status === 'declined') {
  toast = 'Declined';
  editText = `${base}\n\n❌ Declined.`;
} else if (row.status === 'expired') {
  toast = 'Expired';
  editText = `${base}\n\n⌛ Expired. Ask me again if you still want it.`;
} else if (row.status === 'pending') {
  toast = 'Already being processed';
  editText = `${base}\n\n⏳ Already being processed.`;
} else {
  toast = `Already ${row.status}`;
  editText = `${base}\n\nℹ️ Already ${row.status}.`;
}

return [{
  json: { route, toast, editText, proposalId: r.proposalId, payload: row.payload || null, summary: base },
}];

parameters.jsonBody:
={{ JSON.stringify({
  chat_id: $('Route update').first().json.chatId,
  message_id: $('Route update').first().json.messageId,
  text: $json.editText,
  reply_markup: { inline_keyboard: [] }
}) }}
